import React, { useState, useEffect } from 'react';
import './App.css';

/**
 * PENZI Dating App - Main Application Component
 * A dating app that uses SMS-like interactions for user registration and matching
 * 
 * @component
 * @returns {JSX.Element} The rendered app
 */

// ============================================
// API Configuration
// ============================================

const API_BASE = 'http://localhost:5000/api/user';

// ============================================
// Main App Component
// ============================================

function App() {
  // ============================================
  // CORE STATE
  // ============================================

  // Registration flow state
  const [currentStep, setCurrentStep] = useState(0);           // Which step user is on
  const [completedSteps, setCompletedSteps] = useState(new Set()); // Completed step IDs
  const [formData, setFormData] = useState({});                // Form field values
  const [isLoading, setIsLoading] = useState(false);           // Loading indicator
  const [responseMessage, setResponseMessage] = useState('');  // API response message
  const [isSuccess, setIsSuccess] = useState(false);           // Success/fail status
  const [errorDetails, setErrorDetails] = useState('');        // Error details

  // User state
  const [smsConversation, setSmsConversation] = useState([]);  // SMS-like conversation
  const [isLoggedIn, setIsLoggedIn] = useState(false);         // Login status
  const [currentUser, setCurrentUser] = useState(null);        // Current user data
  const [notifications, setNotifications] = useState([]);      // Toast notifications
  const [phoneNumber, setPhoneNumber] = useState('');          // User phone number

  // Activation state
  const [serverStatus, setServerStatus] = useState('checking'); // Server connection status
  const [activationDone, setActivationDone] = useState(false);  // Service activated?
  const [myPhone, setMyPhone] = useState('0712345678');         // Default phone
  const [isFirstTimeUser, setIsFirstTimeUser] = useState(true); // First time user?
  const [showWelcomeBack, setShowWelcomeBack] = useState(false); // Welcome back banner
  const [registrationError, setRegistrationError] = useState(''); // Registration error
  const [userExistsError, setUserExistsError] = useState(false); // User exists warning
  const [showMainMenu, setShowMainMenu] = useState(false);      // Show main menu
  const [registrationComplete, setRegistrationComplete] = useState(false); // Registration done
  const [showSystemResponse, setShowSystemResponse] = useState(false); // System response
  const [systemResponseMessage, setSystemResponseMessage] = useState(''); // System msg
  const [activationKeyword, setActivationKeyword] = useState(''); // Activation keyword

  // ============================================
  // DASHBOARD STATE
  // ============================================

  const [allMatches, setAllMatches] = useState([]);             // All discovered matches
  const [currentMatchIndex, setCurrentMatchIndex] = useState(0); // Pagination for matches
  const [incomingRequests, setIncomingRequests] = useState([]); // Interest requests
  const [currentRequestIndex, setCurrentRequestIndex] = useState(0); // Pagination
  const [myMatches, setMyMatches] = useState([]);               // User's accepted matches
  const [currentMatchListIndex, setCurrentMatchListIndex] = useState(0);
  const [activeTab, setActiveTab] = useState('discover');       // Current dashboard tab
  const [showProfile, setShowProfile] = useState(false);        // Show profile modal
  const [showMatchDetails, setShowMatchDetails] = useState(false); // Show match details
  const [selectedMatch, setSelectedMatch] = useState(null);     // Selected match
  const [isSendingMessage, setIsSendingMessage] = useState(false);
  const [isEditingProfile, setIsEditingProfile] = useState(false);

  // ============================================
  // SEARCH STATE
  // ============================================

  const [searchAgeRange, setSearchAgeRange] = useState('');
  const [searchTown, setSearchTown] = useState('');
  const [searchCounty, setSearchCounty] = useState('');
  const [isSearching, setIsSearching] = useState(false);

  // ============================================
  // CHAT STATE
  // ============================================

  const [chatContacts, setChatContacts] = useState([]);
  const [chatMessages, setChatMessages] = useState({});
  const [newMessage, setNewMessage] = useState('');
  const [selectedChatContact, setSelectedChatContact] = useState(null);

  // ============================================
  // SAMPLE DATA - Used for demonstration
  // ============================================

  const SAMPLE_MATCHES = [
    { 
      id: 1, 
      phone: '0722010203', 
      name: 'Lina Moraa', 
      age: 29, 
      town: 'Nairobi', 
      county: 'Nairobi County', 
      profession: 'Nurse', 
      education: 'Graduate', 
      religion: 'Christian', 
      ethnicity: 'Kikuyu', 
      marital_status: 'single', 
      description: 'Kind-hearted and adventurous. Loves hiking and reading.' 
    },
    { 
      id: 2, 
      phone: '0701223344', 
      name: 'Dorine Gakii', 
      age: 26, 
      town: 'Nakuru', 
      county: 'Nakuru County', 
      profession: 'Teacher', 
      education: 'Diploma', 
      religion: 'Christian', 
      ethnicity: 'Kamba', 
      marital_status: 'single', 
      description: 'Caring and dedicated. Loves children and education.' 
    },
    { 
      id: 3, 
      phone: '0700112233', 
      name: 'Aisha Bahati', 
      age: 27, 
      town: 'Mombasa', 
      county: 'Mombasa County', 
      profession: 'Accountant', 
      education: 'Graduate', 
      religion: 'Muslim', 
      ethnicity: 'Swahili', 
      marital_status: 'single', 
      description: 'Ambitious and hardworking. I love numbers.' 
    },
    { 
      id: 4, 
      phone: '0722040506', 
      name: 'Pamela Nafula', 
      age: 26, 
      town: 'Kisumu', 
      county: 'Kisumu County', 
      profession: 'Engineer', 
      education: 'Post Graduate', 
      religion: 'Christian', 
      ethnicity: 'Luo', 
      marital_status: 'single', 
      description: 'Tech enthusiast. Loves innovation and building solutions.' 
    },
    { 
      id: 5, 
      phone: '0702556677', 
      name: 'Maria Mwende', 
      age: 28, 
      town: 'Kasarani', 
      county: 'Nairobi County', 
      profession: 'Nurse', 
      education: 'Graduate', 
      religion: 'Christian', 
      ethnicity: 'Kamba', 
      marital_status: 'single', 
      description: 'Diligent, loving, dedicated and will make you tick.' 
    },
    { 
      id: 6, 
      phone: '0708990011', 
      name: 'Keziah Cheptab', 
      age: 28, 
      town: 'Eldoret', 
      county: 'Uasin Gishu County', 
      profession: 'Doctor', 
      education: 'Post Graduate', 
      religion: 'Christian', 
      ethnicity: 'Kalenjin', 
      marital_status: 'single', 
      description: 'Passionate about healthcare and community service.' 
    }
  ];

  const SAMPLE_REQUESTS = [
    { 
      id: 101, 
      phone: '0723000001', 
      name: 'Michael Ochieng', 
      age: 30, 
      town: 'Nairobi', 
      county: 'Nairobi County', 
      profession: 'Lawyer', 
      education: 'Post Graduate', 
      religion: 'Christian', 
      ethnicity: 'Luo', 
      marital_status: 'single', 
      message: '💕 Shows interest in you', 
      status: 'pending' 
    },
    { 
      id: 102, 
      phone: '0723000002', 
      name: 'David Kiprop', 
      age: 28, 
      town: 'Eldoret', 
      county: 'Uasin Gishu County', 
      profession: 'Businessman', 
      education: 'Graduate', 
      religion: 'Christian', 
      ethnicity: 'Kalenjin', 
      marital_status: 'single', 
      message: '💕 Shows interest in you', 
      status: 'pending' 
    },
    { 
      id: 103, 
      phone: '0723000003', 
      name: 'Samuel Mwangi', 
      age: 32, 
      town: 'Nakuru', 
      county: 'Nakuru County', 
      profession: 'Developer', 
      education: 'Graduate', 
      religion: 'Christian', 
      ethnicity: 'Kikuyu', 
      marital_status: 'single', 
      message: '💕 Shows interest in you', 
      status: 'pending' 
    }
  ];

  const SAMPLE_MY_MATCHES = [
    { 
      id: 201, 
      phone: '0724000001', 
      name: 'Grace Akinyi', 
      age: 27, 
      town: 'Kisumu', 
      county: 'Kisumu County', 
      profession: 'Nurse', 
      education: 'Graduate', 
      religion: 'Christian', 
      ethnicity: 'Luo', 
      marital_status: 'single', 
      status: 'accepted' 
    },
    { 
      id: 202, 
      phone: '0724000002', 
      name: 'Peter Mwangi', 
      age: 29, 
      town: 'Nakuru', 
      county: 'Nakuru County', 
      profession: 'Engineer', 
      education: 'Graduate', 
      religion: 'Christian', 
      ethnicity: 'Kikuyu', 
      marital_status: 'single', 
      status: 'accepted' 
    },
    { 
      id: 203, 
      phone: '0724000003', 
      name: 'Sarah Wanjiru', 
      age: 25, 
      town: 'Thika', 
      county: 'Kiambu County', 
      profession: 'Designer', 
      education: 'Graduate', 
      religion: 'Christian', 
      ethnicity: 'Kikuyu', 
      marital_status: 'single', 
      status: 'accepted' 
    }
  ];

  // ============================================
  // STEPS DEFINITION - Registration Flow
  // ============================================

  const STEPS = [
    {
      id: 1,
      title: 'Service Activation',
      subtitle: 'Enter PENZI to activate',
      icon: '💑',
      isActivation: true,
      systemResponse: `Welcome to our dating service with 6000 potential dating partners!\n\nTo register, enter the following details:\nstart#name#age#gender#county#town\n\nExample:\nstart#John Doe#26#Male#Nakuru#Naivasha`
    },
    {
      id: 2,
      title: 'Service Registration',
      subtitle: 'Create your account',
      icon: '📝',
      fields: [
        { key: 'phone_number', label: '📱 Phone Number', placeholder: '0712345678', type: 'tel' },
        { key: 'name', label: '👤 Full Name', placeholder: 'Jamal Jalang\'o', type: 'text' },
        { key: 'age', label: '🎂 Age', placeholder: '29', type: 'number' },
        { key: 'gender', label: '⚤ Gender', type: 'select', options: ['Male', 'Female', 'Other'] },
        { key: 'county', label: '📍 County', placeholder: 'Mombasa', type: 'text' },
        { key: 'town', label: '🏙️ Town/City', placeholder: 'Bamburi', type: 'text' }
      ],
      isRegistration: true,
      userMessage: (data) => `start#${data.name}#${data.age}#${data.gender}#${data.county}#${data.town}`,
      systemResponse: (data) => `Your profile has been created successfully ${data.name}.\n\nSMS details#levelOfEducation#profession#maritalStatus#religion#ethnicity to 22141.\nE.g. details#diploma#driver#single#christian#mijikenda`
    },
    {
      id: 3,
      title: 'Details Registration',
      subtitle: 'Complete your profile',
      icon: '📋',
      fields: [
        { key: 'education_level', label: '🎓 Education Level', type: 'select', options: ['Primary', 'Secondary', 'Certificate', 'Diploma', 'Graduate', 'Post Graduate'] },
        { key: 'profession', label: '💼 Profession', placeholder: 'Accountant', type: 'text' },
        { key: 'marital_status', label: '💍 Marital Status', type: 'select', options: ['single', 'married', 'divorced', 'widowed', 'separated'] },
        { key: 'religion', label: '⛪ Religion', placeholder: 'Muslim', type: 'text' },
        { key: 'ethnicity', label: '🌍 Ethnicity', placeholder: 'Somali', type: 'text' }
      ],
      isDetails: true,
      userMessage: (data) => `details#${data.education_level}#${data.profession}#${data.marital_status}#${data.religion}#${data.ethnicity}`,
      systemResponse: 'This is the last stage of registration. SMS a brief description of yourself to 22141 starting with the word MYSELF.\nE.g., MYSELF chocolate, lovely, sexy etc.'
    },
    {
      id: 4,
      title: 'Self-Description',
      subtitle: 'Tell us about yourself',
      icon: '💭',
      fields: [{ key: 'description', label: 'Describe yourself', placeholder: 'tall, dark and handsome', type: 'textarea' }],
      isSelfDescription: true,
      userMessage: (data) => `MYSELF ${data.description}`,
      systemResponse: 'You are now registered for dating! To search for a MPENZI, SMS match#age#town to 22141 and meet the person of your dreams.\nE.g., match#23-25#Kisumu'
    }
  ];

  // ============================================
  // API CALL FUNCTIONS
  // ============================================

  /**
   * Make API calls to the backend server
   * @param {string} endpoint - API endpoint (e.g., '/register')
   * @param {string} method - HTTP method (GET, POST, etc.)
   * @param {Object} body - Request body data
   * @returns {Promise<Object>} API response data
   */
  const callApi = async (endpoint, method, body = null) => {
    try {
      const options = {
        method: method,
        headers: { 'Content-Type': 'application/json' }
      };
      if (body) {
        options.body = JSON.stringify(body);
      }
      const response = await fetch(`${API_BASE}${endpoint}`, options);
      const data = await response.json();
      console.log(`API ${method} ${endpoint}:`, data);
      return data;
    } catch (error) {
      console.error('API Error:', error);
      return null;
    }
  };

  // ============================================
  // LOAD SAVED STATE FROM LOCAL STORAGE
  // ============================================

  useEffect(() => {
    try {
      const saved = localStorage.getItem('penziState');
      if (saved) {
        const parsed = JSON.parse(saved);

        // If user is logged in, restore their session
        if (parsed.currentUser && parsed.isLoggedIn) {
          setCurrentUser(parsed.currentUser);
          setIsLoggedIn(true);
          setAllMatches(parsed.allMatches || []);
          setIncomingRequests(parsed.incomingRequests || []);
          setMyMatches(parsed.myMatches || []);
          setChatContacts(parsed.chatContacts || []);
          setChatMessages(parsed.chatMessages || {});
          setActiveTab(parsed.activeTab || 'discover');
          setMyPhone(parsed.myPhone || '0712345678');
          setActivationDone(parsed.activationDone || false);
          setShowWelcomeBack(true);
          setShowMainMenu(true);
          setCompletedSteps(new Set(parsed.completedSteps || []));

          // Show welcome back notification
          setTimeout(() => {
            addNotification(`👋 Welcome back, ${parsed.currentUser.name}!`);
          }, 500);

          setIsFirstTimeUser(false);
        } else {
          // Restore registration state
          setCurrentStep(parsed.currentStep || 0);
          setCompletedSteps(new Set(parsed.completedSteps || []));
          setSmsConversation(parsed.smsConversation || []);
          setPhoneNumber(parsed.phoneNumber || '');
          setActivationDone(parsed.activationDone || false);
          setMyPhone(parsed.myPhone || '0712345678');
          if (parsed.currentUser) {
            setCurrentUser(parsed.currentUser);
          }
          setIsFirstTimeUser(true);
        }
      }
    } catch (e) {
      console.warn('Could not load saved state:', e);
      setIsFirstTimeUser(true);
    }
  }, []);

  // ============================================
  // SAVE STATE TO LOCAL STORAGE
  // ============================================

  useEffect(() => {
    try {
      const stateToSave = {
        currentStep,
        completedSteps: Array.from(completedSteps),
        smsConversation,
        currentUser,
        isLoggedIn,
        phoneNumber,
        activationDone,
        allMatches,
        incomingRequests,
        myMatches,
        chatContacts,
        chatMessages,
        activeTab,
        myPhone,
        showMainMenu
      };
      localStorage.setItem('penziState', JSON.stringify(stateToSave));
    } catch (e) {
      console.warn('Could not save state:', e);
    }
  }, [
    currentStep, 
    completedSteps, 
    smsConversation, 
    currentUser, 
    isLoggedIn, 
    phoneNumber, 
    activationDone, 
    allMatches, 
    incomingRequests, 
    myMatches, 
    chatContacts, 
    chatMessages, 
    activeTab, 
    myPhone, 
    showMainMenu
  ]);

  // ============================================
  // CHECK SERVER CONNECTION
  // ============================================

  useEffect(() => {
    checkServer();
  }, []);

  /**
   * Check if the backend server is reachable
   */
  const checkServer = async () => {
    try {
      const response = await fetch(`${API_BASE}/activate`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ penzi: 'penzi' })
      });
      if (response.ok || response.status === 400 || response.status === 405) {
        setServerStatus('connected');
      } else {
        setServerStatus('error');
      }
    } catch (error) {
      setServerStatus('error');
    }
  };

  // ============================================
  // HELPER FUNCTIONS
  // ============================================

  /**
   * Update form data when input changes
   */
  const handleInputChange = (field, value) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  /**
   * Add a message to the SMS conversation
   */
  const addToConversation = (sender, message, isSystem = false) => {
    const entry = {
      id: Date.now(),
      sender: sender,
      message: message,
      isSystem: isSystem,
      timestamp: new Date().toLocaleTimeString()
    };
    setSmsConversation(prev => [...prev, entry]);
  };

  /**
   * Add a toast notification
   */
  const addNotification = (message, type = 'success') => {
    const id = Date.now();
    setNotifications(prev => [...prev, { id, message, type }]);
    // Auto-dismiss after 5 seconds
    setTimeout(() => {
      setNotifications(prev => prev.filter(n => n.id !== id));
    }, 5000);
  };

  /**
   * Calculate registration progress percentage
   */
  const getProgress = () => {
    if (!activationDone) return 0;
    return Math.round((completedSteps.size / STEPS.length) * 100);
  };

  /**
   * Navigate to a specific step
   */
  const goToStep = (index) => {
    if (index >= 0 && index < STEPS.length) {
      setCurrentStep(index);
      setShowSystemResponse(false);
      setSystemResponseMessage('');
    }
  };

  // ============================================
  // LOGOUT / EXIT / HOME FUNCTIONS
  // ============================================

  /**
   * Log out the user and clear all state
   */
  const handleLogout = () => {
    localStorage.removeItem('penziState');
    setIsLoggedIn(false);
    setCurrentUser(null);
    setAllMatches([]);
    setIncomingRequests([]);
    setMyMatches([]);
    setChatContacts([]);
    setChatMessages({});
    setSelectedChatContact(null);
    setSmsConversation([]);
    setActivationDone(false);
    setCurrentStep(0);
    setCompletedSteps(new Set());
    setShowWelcomeBack(false);
    setIsFirstTimeUser(true);
    setUserExistsError(false);
    setRegistrationError('');
    setShowMainMenu(false);
    setRegistrationComplete(false);
    setShowSystemResponse(false);
    setSystemResponseMessage('');
    setActivationKeyword('');
    addNotification('👋 Logged out successfully!');
  };

  /**
   * Go back to the main menu
   */
  const goHome = () => {
    setActiveTab('discover');
    setSelectedChatContact(null);
    setShowProfile(false);
    setShowMatchDetails(false);
    setSelectedMatch(null);
    setShowMainMenu(true);
    addNotification('🏠 Returned to home');
  };

  // ============================================
  // SEARCH MATCHES
  // ============================================

  /**
   * Perform search with current filters
   */
  const performSearch = () => {
    setIsSearching(true);

    // Simulate API delay
    setTimeout(() => {
      let filtered = [...SAMPLE_MATCHES];

      // Filter by age range
      if (searchAgeRange && searchAgeRange.trim() !== '') {
        const [min, max] = searchAgeRange.split('-').map(Number);
        if (!isNaN(min) && !isNaN(max)) {
          filtered = filtered.filter(m => m.age >= min && m.age <= max);
        }
      }

      // Filter by town
      if (searchTown && searchTown.trim() !== '') {
        const townLower = searchTown.toLowerCase().trim();
        filtered = filtered.filter(m => 
          m.town.toLowerCase().includes(townLower)
        );
      }

      // Filter by county
      if (searchCounty && searchCounty.trim() !== '') {
        const countyLower = searchCounty.toLowerCase().trim();
        filtered = filtered.filter(m => 
          m.county && m.county.toLowerCase().includes(countyLower)
        );
      }

      setAllMatches(filtered);

      if (filtered.length === 0) {
        addNotification('🔍 No matches found. Try adjusting your search criteria.', 'warning');
      } else {
        addNotification(`✅ Found ${filtered.length} matches!`);
      }

      setIsSearching(false);
    }, 500);
  };

  /**
   * Reset search filters
   */
  const resetSearch = () => {
    setSearchAgeRange('');
    setSearchTown('');
    setSearchCounty('');
    setAllMatches(SAMPLE_MATCHES);
    addNotification('🔄 Search reset. Showing all matches.');
  };

  // ============================================
  // ACTIVATE SERVICE
  // ============================================

  /**
   * Activate the service with the keyword
   */
  const activateService = async () => {
    setIsLoading(true);
    setResponseMessage('');
    setIsSuccess(false);
    setErrorDetails('');

    try {
      const result = await callApi('/activate', 'POST', { penzi: activationKeyword || 'PENZI' });

      if (result && result.status === 'success') {
        setSystemResponseMessage(STEPS[0].systemResponse);
        setShowSystemResponse(true);

        addToConversation('📱 You', activationKeyword || 'PENZI', false);
        addToConversation('🤖 System', STEPS[0].systemResponse, true);
        setActivationDone(true);
        setResponseMessage('✅ Service activated successfully!');
        setIsSuccess(true);
        setCompletedSteps(prev => new Set([...prev, 0]));
        addNotification('✅ Service activated!');
        setMyPhone('0712345678');
        setActivationKeyword('');
      } else {
        setResponseMessage('❌ Invalid activation keyword. Please enter PENZI to continue.');
        setIsSuccess(false);
        setErrorDetails('Invalid activation keyword. Please enter PENZI to continue.');
        addNotification('❌ Invalid activation keyword', 'error');
      }
    } catch (error) {
      console.error('❌ Activation Error:', error);
      setResponseMessage('❌ Network error. Please check your connection.');
      setIsSuccess(false);
      setErrorDetails(error.message);
      addNotification('❌ Network error', 'error');
    } finally {
      setIsLoading(false);
    }
  };

  // ============================================
  // PROCEED TO REGISTRATION
  // ============================================

  /**
   * Move from activation to registration
   */
  const proceedToRegistration = () => {
    goToStep(1);
    setShowSystemResponse(false);
    addNotification('📝 Proceeding to Registration...');
  };

  // ============================================
  // EXECUTE API - Registration Steps
  // ============================================

  /**
   * Execute API call for the current registration step
   */
  const executeApi = async () => {
    const step = STEPS[currentStep];
    setIsLoading(true);
    setResponseMessage('');
    setIsSuccess(false);
    setErrorDetails('');
    setRegistrationError('');
    setUserExistsError(false);

    try {
      let phone = formData.phone_number || phoneNumber || myPhone || '0712345678';

      // Handle registration step (Step 1)
      if (step.isRegistration) {
        const data = {
          phone_number: formData.phone_number,
          name: formData.name,
          age: formData.age,
          gender: formData.gender,
          county: formData.county,
          town: formData.town
        };
        const result = await callApi('/register', 'POST', data);

        // Check if user already exists
        if (result && result.status === 'error' && result.message === 'User already exists') {
          setUserExistsError(true);
          setRegistrationError('⚠️ User already exists. Proceeding to dashboard.');
          addNotification('⚠️ User already exists. Proceeding to dashboard.', 'warning');

          // Create user from form data
          const existingUser = {
            phone: formData.phone_number || phone || '0712345678',
            name: formData.name || 'User',
            age: formData.age || '26',
            town: formData.town || 'Nairobi',
            county: formData.county || 'Nairobi'
          };
          setCurrentUser(existingUser);
          setIsLoggedIn(true);
          setShowMainMenu(true);
          setIsFirstTimeUser(false);
          setCompletedSteps(prev => new Set([...prev, currentStep]));

          const userMsg = step.userMessage(formData);
          addToConversation('📱 You', userMsg, false);
          addToConversation('🤖 System', '✅ User already exists! Proceeding to dashboard.', true);

          setIsLoading(false);
          return;
        }

        // Handle successful registration
        if (result && result.status === 'success') {
          const userMsg = step.userMessage(formData);
          const sysMsg = result.message || step.systemResponse(formData);

          setSystemResponseMessage(sysMsg);
          setShowSystemResponse(true);

          addToConversation('📱 You', userMsg, false);
          addToConversation('🤖 System', sysMsg, true);
          setMyPhone(formData.phone_number || '0712345678');
          setResponseMessage('✅ Registration complete!');
          setIsSuccess(true);
          setCompletedSteps(prev => new Set([...prev, currentStep]));
          addNotification('✅ Registration complete!');
          setRegistrationError('');

          // Create user object
          const newUser = {
            phone: formData.phone_number || phone || '0712345678',
            name: formData.name || 'User',
            age: formData.age || '26',
            town: formData.town || 'Nairobi',
            county: formData.county || 'Nairobi'
          };
          setCurrentUser(newUser);
          setIsLoggedIn(true);
          setShowMainMenu(true);
          setIsFirstTimeUser(false);
        } else {
          const errorMsg = result?.message || 'Registration failed. Please try again.';
          setResponseMessage('❌ ' + errorMsg);
          setIsSuccess(false);
          setRegistrationError(errorMsg);
        }
      }

      // Handle details step (Step 2)
      else if (step.isDetails) {
        const data = {
          education_level: formData.education_level,
          profession: formData.profession,
          marital_status: formData.marital_status,
          religion: formData.religion,
          ethnicity: formData.ethnicity
        };
        const result = await callApi(`/${phone}/complete-profile`, 'POST', data);

        if (result && result.status === 'success') {
          const userMsg = step.userMessage(formData);
          const sysMsg = result.message || step.systemResponse;

          setSystemResponseMessage(sysMsg);
          setShowSystemResponse(true);

          addToConversation('📱 You', userMsg, false);
          addToConversation('🤖 System', sysMsg, true);
          setResponseMessage('✅ Profile completed!');
          setIsSuccess(true);
          setCompletedSteps(prev => new Set([...prev, currentStep]));
          addNotification('✅ Profile completed!');

          // Update current user
          if (currentUser) {
            setCurrentUser(prev => ({
              ...prev,
              education: formData.education_level,
              profession: formData.profession,
              marital_status: formData.marital_status,
              religion: formData.religion,
              ethnicity: formData.ethnicity
            }));
          }
        } else {
          setResponseMessage('❌ ' + (result?.message || 'Profile completion failed.'));
          setIsSuccess(false);
        }
      }

      // Handle self-description step (Step 3)
      else if (step.isSelfDescription) {
        const result = await callApi(`/${phone}/self-description`, 'POST', { description: formData.description });

        if (result && result.status === 'success') {
          const userMsg = step.userMessage(formData);
          const sysMsg = result.message || step.systemResponse;

          setSystemResponseMessage(sysMsg);
          setShowSystemResponse(true);

          addToConversation('📱 You', userMsg, false);
          addToConversation('🤖 System', sysMsg, true);
          setResponseMessage('✅ Self-description added!');
          setIsSuccess(true);
          setCompletedSteps(prev => new Set([...prev, currentStep]));
          addNotification('✅ Registration complete!');
          setRegistrationComplete(true);

          // Update current user
          if (currentUser) {
            setCurrentUser(prev => ({
              ...prev,
              description: formData.description
            }));
          }

          // Log in if not already
          if (!isLoggedIn) {
            const user = {
              phone: formData.phone_number || phone || '0712345678',
              name: formData.name || 'User',
              age: formData.age || '26',
              town: formData.town || 'Nairobi',
              county: formData.county || 'Nairobi',
              description: formData.description
            };
            setCurrentUser(user);
            setIsLoggedIn(true);
          }
          setShowMainMenu(true);
          setIsFirstTimeUser(false);
          addNotification('🎉 Welcome to PENZI Dating!');
        } else {
          setResponseMessage('❌ ' + (result?.message || 'Self-description failed.'));
          setIsSuccess(false);
        }
      }

    } catch (error) {
      console.error('❌ API Error:', error);
      setResponseMessage('❌ Network error. Please check your connection.');
      setIsSuccess(false);
      setErrorDetails(error.message);
      addNotification('❌ Network error', 'error');
