                <button type="button" className="btn-secondary" onClick={() => setIsEditingProfile(false)}>Cancel</button>
              </div>
            </form>
          )}
        </div>
      </div>
    );
  };

  // ============================================
  // RENDER CHAT
  // ============================================

  const renderChat = () => {
    if (selectedChatContact) {
      const messages = chatMessages[selectedChatContact.phone] || [];

      return (
        <div className="chat-view">
          <div className="chat-header-whatsapp">
            <div className="chat-header-left">
              <button className="btn-back-chat" onClick={() => setSelectedChatContact(null)}>←</button>
              <div className="chat-avatar">{selectedChatContact.name?.charAt(0) || '?'}</div>
              <div className="chat-contact-info">
                <div className="chat-contact-name">{selectedChatContact.name}</div>
                <div className="chat-contact-status">
                  {selectedChatContact.online ? '🟢 Online' : 'Last seen recently'}
                </div>
              </div>
            </div>
            <div className="chat-header-right">
              <button className="btn-chat-action">👤</button>
            </div>
          </div>

          <div className="chat-messages-whatsapp">
            {messages.length === 0 ? (
              <div className="empty-state">
                <div className="empty-icon">💬</div>
                <h3>No Messages Yet</h3>
                <p>Start a conversation with {selectedChatContact.name}</p>
              </div>
            ) : (
              messages.map((msg) => (
                <div key={msg.id} className={`message-bubble ${msg.isMine ? 'sent' : 'received'}`}>
                  {!msg.isMine && <div className="message-sender">{msg.sender}</div>}
                  <div className="message-content">
                    <p>{msg.message}</p>
                    <span className="message-time">{msg.time}</span>
                  </div>
                </div>
              ))
            )}
          </div>

          <div className="chat-input-whatsapp">
            <input
              type="text"
              value={newMessage}
              onChange={(e) => setNewMessage(e.target.value)}
              placeholder={`Message ${selectedChatContact.name}...`}
              onKeyPress={(e) => {
                if (e.key === 'Enter' && newMessage.trim()) {
                  const msg = {
                    id: Date.now(),
                    sender: 'You',
                    message: newMessage,
                    time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
                    isMine: true
                  };
                  setChatMessages(prev => ({
                    ...prev,
                    [selectedChatContact.phone]: [...(prev[selectedChatContact.phone] || []), msg]
                  }));
                  setNewMessage('');
                }
              }}
            />
            <button 
              className="btn-send-whatsapp" 
              onClick={() => {
                if (!newMessage.trim()) return;
                const msg = {
                  id: Date.now(),
                  sender: 'You',
                  message: newMessage,
                  time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
                  isMine: true
                };
                setChatMessages(prev => ({
                  ...prev,
                  [selectedChatContact.phone]: [...(prev[selectedChatContact.phone] || []), msg]
                }));
                setNewMessage('');
              }}
              disabled={!newMessage.trim()}
            >
              📤
            </button>
          </div>
        </div>
      );
    }

    return (
      <div className="chat-contact-list-whatsapp">
        <div className="chat-list-header-whatsapp">
          <h3>💬 Chats</h3>
          <span className="chat-list-count">{chatContacts.length} chats</span>
        </div>

        {chatContacts.length === 0 ? (
          <div className="empty-state">
            <div className="empty-icon">💬</div>
            <h3>No Conversations</h3>
            <p>Start chatting with your matches from the Matches tab</p>
            <button className="btn-primary" onClick={() => setActiveTab('matches')}>
              💕 View Matches
            </button>
          </div>
        ) : (
          <div className="chat-contacts-list">
            {chatContacts.map((contact) => (
              <div 
                key={contact.phone} 
                className="chat-contact-item-whatsapp"
                onClick={() => setSelectedChatContact(contact)}
              >
                <div className="contact-avatar-whatsapp">
                  {contact.name?.charAt(0) || '?'}
                </div>
                <div className="contact-info-whatsapp">
                  <div className="contact-name-whatsapp">{contact.name}</div>
                  <div className="contact-last-message-whatsapp">
                    {contact.lastMessage || 'Start chatting...'}
                  </div>
                </div>
                <div className="contact-meta-whatsapp">
                  <div className="contact-time-whatsapp">{contact.lastMessageTime || 'Now'}</div>
                  {contact.unread > 0 && (
                    <div className="contact-unread-whatsapp">{contact.unread}</div>
                  )}
                  {contact.online && (
                    <div className="contact-online-dot"></div>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    );
  };

  // ============================================
  // RENDER DISCOVER TABLE
  // ============================================

  const renderDiscoverTable = () => {
    return (
      <div className="discover-table-container">
        <div className="search-bar-container">
          <div className="search-bar-header">
            <span className="search-icon">🔍</span>
            <span className="search-title">Search Matches</span>
          </div>
          <div className="search-bar-fields">
            <div className="search-field">
              <label>Age Range</label>
              <input
                type="text"
                value={searchAgeRange}
                onChange={(e) => setSearchAgeRange(e.target.value)}
                placeholder="e.g., 20-40"
                className="search-input"
              />
            </div>
            <div className="search-field">
              <label>Town</label>
              <input
                type="text"
                value={searchTown}
                onChange={(e) => setSearchTown(e.target.value)}
                placeholder="Enter town name"
                className="search-input"
              />
            </div>
            <div className="search-field">
              <label>County</label>
              <input
                type="text"
                value={searchCounty}
                onChange={(e) => setSearchCounty(e.target.value)}
                placeholder="Enter county name"
                className="search-input"
              />
            </div>
            <div className="search-actions">
              <button
                onClick={performSearch}
                disabled={isSearching}
                className="btn-search"
              >
                {isSearching ? '⏳ Searching...' : '🔍 Search'}
              </button>
              <button
                onClick={resetSearch}
                className="btn-reset"
              >
                🔄 Reset
              </button>
            </div>
          </div>
        </div>

        {allMatches.length === 0 ? (
          <div className="empty-state">
            <div className="empty-icon">🔍</div>
            <h2>No Matches Found</h2>
            <p>Try adjusting your search criteria or load sample matches</p>
            <div className="empty-actions">
              <button className="btn-primary" onClick={() => {
                setAllMatches(SAMPLE_MATCHES);
                addNotification(`✅ Loaded ${SAMPLE_MATCHES.length} matches!`);
              }}>
                📥 Load Sample Matches
              </button>
            </div>
          </div>
        ) : (
          <>
            <div className="table-header">
              <div className="table-header-left">
                <h3>👥 Matches Found</h3>
                <span className="match-count">{allMatches.length} results</span>
              </div>
            </div>

            <div className="matches-table-wrapper">
              <table className="matches-table">
                <thead>
                  <tr>
                    <th>#</th>
                    <th>Name</th>
                    <th>Age</th>
                    <th>Town</th>
                    <th>County</th>
                    <th>Profession</th>
                    <th>Education</th>
                    <th>Religion</th>
                    <th>Ethnicity</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {allMatches.map((match, index) => (
                    <tr key={match.id} className="match-row">
                      <td className="match-number">{index + 1}</td>
                      <td className="match-name-cell">
                        <div className="match-avatar-small" onClick={() => {
                          setSelectedMatch(match);
                          setShowMatchDetails(true);
                        }}>
                          {match.name?.charAt(0) || '?'}
                        </div>
                        <span className="match-name-text" onClick={() => {
                          setSelectedMatch(match);
                          setShowMatchDetails(true);
                        }}>
                          {match.name}
                        </span>
                      </td>
                      <td>{match.age}</td>
                      <td>{match.town}</td>
                      <td>{match.county || 'N/A'}</td>
                      <td>{match.profession || 'N/A'}</td>
                      <td>{match.education || 'N/A'}</td>
                      <td>{match.religion || 'N/A'}</td>
                      <td>{match.ethnicity || 'N/A'}</td>
                      <td className="match-actions-cell">
                        <button className="btn-view" onClick={() => {
                          setSelectedMatch(match);
                          setShowMatchDetails(true);
                        }}>👤</button>
                        <button className="btn-interest" onClick={() => {
                          addNotification(`💕 Interest sent to ${match.name}!`);
                        }}>💕</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            <div className="table-navigation">
              <button 
                className="nav-btn"
                onClick={() => setCurrentMatchIndex(Math.max(0, currentMatchIndex - 10))}
                disabled={currentMatchIndex === 0}
              >
                ⬅ Previous
              </button>
              <span className="match-counter">
                Showing {currentMatchIndex + 1} - {Math.min(currentMatchIndex + 10, allMatches.length)} of {allMatches.length}
              </span>
              <button 
                className="nav-btn"
                onClick={() => {
                  if (currentMatchIndex + 10 >= allMatches.length) {
                    addNotification('📥 All matches loaded.');
                  } else {
                    setCurrentMatchIndex(Math.min(allMatches.length - 1, currentMatchIndex + 10));
                  }
                }}
              >
                Next ➡
              </button>
            </div>
          </>
        )}
      </div>
    );
  };

  // ============================================
  // RENDER REQUESTS TABLE
  // ============================================

  const renderRequestsTable = () => {
    if (incomingRequests.length === 0) {
      return (
        <div className="empty-state">
          <div className="empty-icon">📬</div>
          <h2>No Requests</h2>
          <p>When someone shows interest in you, it will appear here</p>
          <button className="btn-primary" onClick={() => {
            setIncomingRequests(SAMPLE_REQUESTS);
            addNotification(`✅ Loaded ${SAMPLE_REQUESTS.length} requests!`);
          }}>
            📥 Load Demo Requests
          </button>
        </div>
      );
    }

    return (
      <div className="discover-table-container">
        <div className="table-header">
          <div className="table-header-left">
            <h3>📬 Incoming Requests</h3>
            <span className="match-count">{incomingRequests.length} requests</span>
          </div>
        </div>

        <div className="matches-table-wrapper">
          <table className="matches-table">
            <thead>
              <tr>
                <th>#</th>
                <th>Name</th>
                <th>Age</th>
                <th>Town</th>
                <th>County</th>
                <th>Profession</th>
                <th>Message</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {incomingRequests.map((request, index) => (
                <tr key={request.id} className="match-row">
                  <td className="match-number">{index + 1}</td>
                  <td className="match-name-cell">
                    <div className="match-avatar-small" onClick={() => {
                      setSelectedMatch(request);
                      setShowMatchDetails(true);
                    }}>
                      {request.name?.charAt(0) || '?'}
                    </div>
                    <span className="match-name-text" onClick={() => {
                      setSelectedMatch(request);
                      setShowMatchDetails(true);
                    }}>
                      {request.name}
                    </span>
                  </td>
                  <td>{request.age}</td>
                  <td>{request.town}</td>
                  <td>{request.county || 'N/A'}</td>
                  <td>{request.profession || 'N/A'}</td>
                  <td className="request-message-cell">{request.message}</td>
                  <td className="match-actions-cell">
                    <button className="btn-view" onClick={() => {
                      setSelectedMatch(request);
                      setShowMatchDetails(true);
                    }}>👤</button>
                    <button className="btn-accept" onClick={() => {
                      const newMatch = {
                        id: Date.now(),
                        phone: request.phone,
                        name: request.name,
                        age: request.age,
                        town: request.town,
                        county: request.county,
                        profession: request.profession,
                        status: 'accepted'
                      };
                      setMyMatches(prev => [...prev, newMatch]);
                      setIncomingRequests(prev => prev.filter(r => r.id !== request.id));
                      addNotification(`✅ You accepted ${request.name}'s request!`);
                    }}>✅</button>
                    <button className="btn-decline" onClick={() => {
                      setIncomingRequests(prev => prev.filter(r => r.id !== request.id));
                      addNotification(`❌ You declined ${request.name}'s request.`);
                    }}>❌</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        <div className="table-navigation">
          <button 
            className="nav-btn"
            onClick={() => setCurrentRequestIndex(Math.max(0, currentRequestIndex - 5))}
            disabled={currentRequestIndex === 0}
          >
            ⬅ Previous
          </button>
          <span className="match-counter">
            {currentRequestIndex + 1} of {incomingRequests.length}
          </span>
          <button 
            className="nav-btn"
            onClick={() => setCurrentRequestIndex(Math.min(incomingRequests.length - 1, currentRequestIndex + 5))}
            disabled={currentRequestIndex >= incomingRequests.length - 1}
          >
            Next ➡
          </button>
        </div>
      </div>
    );
  };

  // ============================================
  // RENDER MY MATCHES TABLE
  // ============================================

  const renderMyMatchesTable = () => {
    if (myMatches.length === 0) {
      return (
        <div className="empty-state">
          <div className="empty-icon">💕</div>
          <h2>No Matches Yet</h2>
          <p>Start discovering and accepting requests to find your match</p>
          <div className="empty-actions">
            <button className="btn-primary" onClick={() => {
              setMyMatches(SAMPLE_MY_MATCHES);
              addNotification(`✅ Loaded ${SAMPLE_MY_MATCHES.length} matches!`);
            }}>
              📥 Load Sample Matches
            </button>
            <button className="btn-secondary" onClick={() => setActiveTab('discover')}>
              🔍 Discover People
            </button>
          </div>
        </div>
      );
    }

    return (
      <div className="discover-table-container">
        <div className="table-header">
          <div className="table-header-left">
            <h3>💕 Your Matches</h3>
            <span className="match-count">{myMatches.length} matches</span>
          </div>
        </div>

        <div className="matches-table-wrapper">
          <table className="matches-table">
            <thead>
              <tr>
                <th>#</th>
                <th>Name</th>
                <th>Age</th>
                <th>Town</th>
                <th>County</th>
                <th>Profession</th>
                <th>Status</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {myMatches.map((match, index) => (
                <tr key={match.id} className="match-row">
                  <td className="match-number">{index + 1}</td>
                  <td className="match-name-cell">
                    <div className="match-avatar-small" onClick={() => {
                      setSelectedMatch(match);
                      setShowMatchDetails(true);
                    }}>
                      {match.name?.charAt(0) || '?'}
                    </div>
                    <span className="match-name-text" onClick={() => {
                      setSelectedMatch(match);
                      setShowMatchDetails(true);
                    }}>
                      {match.name}
                    </span>
                  </td>
                  <td>{match.age}</td>
                  <td>{match.town}</td>
                  <td>{match.county || 'N/A'}</td>
                  <td>{match.profession || 'N/A'}</td>
                  <td><span className="status-accepted">✅ Accepted</span></td>
                  <td className="match-actions-cell">
                    <button className="btn-view" onClick={() => {
                      setSelectedMatch(match);
                      setShowMatchDetails(true);
                    }}>👤</button>
                    <button className="btn-chat" onClick={() => {
                      if (!chatContacts.some(c => c.phone === match.phone)) {
                        const newContact = {
                          phone: match.phone,
                          name: match.name,
                          lastMessage: 'Start chatting...',
                          lastMessageTime: 'Now',
                          unread: 0,
                          online: true
                        };
                        setChatContacts(prev => [newContact, ...prev]);
                      }
                      setSelectedChatContact(match);
                      setActiveTab('chat');
                      addNotification(`💬 Chat started with ${match.name}`);
                    }}>💬</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        <div className="table-navigation">
          <button 
            className="nav-btn"
            onClick={() => setCurrentMatchListIndex(Math.max(0, currentMatchListIndex - 5))}
            disabled={currentMatchListIndex === 0}
          >
            ⬅ Previous
          </button>
          <span className="match-counter">
            {currentMatchListIndex + 1} of {myMatches.length}
          </span>
          <button 
            className="nav-btn"
            onClick={() => setCurrentMatchListIndex(Math.min(myMatches.length - 1, currentMatchListIndex + 5))}
            disabled={currentMatchListIndex >= myMatches.length - 1}
          >
            Next ➡
          </button>
        </div>
      </div>
    );
  };

  // ============================================
  // RENDER DASHBOARD
  // ============================================

  const renderDashboard = () => {
    return (
      <div className="dashboard-container">
        <header className="dashboard-header">
          <div className="header-left">
            <button className="btn-home" onClick={goHome} title="Home">🏠</button>
            <h1>💑 PENZI</h1>
            <span className="live-badge">❤️ Live</span>
          </div>
          <div className="header-right">
            <span className="user-greeting">👋 {currentUser?.name || 'User'}</span>
            <button className="btn-menu" onClick={() => setShowMainMenu(true)} title="Menu">📋</button>
            <button className="profile-btn" onClick={() => setShowProfile(true)} title="View Profile">👤</button>
            <button className="btn-exit" onClick={handleLogout} title="Logout">🚪</button>
          </div>
        </header>

        <nav className="dashboard-nav">
          <button 
            className={`nav-item ${activeTab === 'discover' ? 'active' : ''}`} 
            onClick={() => {
              setActiveTab('discover');
              if (allMatches.length === 0) {
                setAllMatches(SAMPLE_MATCHES);
              }
            }}
          >
            🔍 Discover
            <span className="nav-badge">{allMatches.length}</span>
          </button>
          <button 
            className={`nav-item ${activeTab === 'matches' ? 'active' : ''}`} 
            onClick={() => {
              setActiveTab('matches');
              if (myMatches.length === 0) {
                setMyMatches(SAMPLE_MY_MATCHES);
              }
            }}
          >
            💕 Matches
            <span className="nav-badge">{myMatches.length}</span>
          </button>
          <button 
            className={`nav-item ${activeTab === 'requests' ? 'active' : ''}`} 
            onClick={() => {
              setActiveTab('requests');
              if (incomingRequests.length === 0) {
                setIncomingRequests(SAMPLE_REQUESTS);
              }
            }}
          >
            📬 Requests
            {incomingRequests.length > 0 && <span className="nav-badge red">{incomingRequests.length}</span>}
          </button>
          <button 
            className={`nav-item ${activeTab === 'chat' ? 'active' : ''}`} 
            onClick={() => setActiveTab('chat')}
          >
            💬 Chat
            {chatContacts.length > 0 && <span className="nav-badge">{chatContacts.length}</span>}
          </button>
        </nav>

        <main className="dashboard-content">
          {activeTab === 'discover' && renderDiscoverTable()}
          {activeTab === 'matches' && renderMyMatchesTable()}
          {activeTab === 'requests' && renderRequestsTable()}
          {activeTab === 'chat' && (
            <div className="chat-container-whatsapp">
              {renderChat()}
            </div>
          )}
        </main>

        {showMatchDetails && renderProfileModal()}
        {showProfile && renderProfileDetails()}
      </div>
    );
  };

  // ============================================
  // MAIN RENDER
  // ============================================

  return (
    <div className="app">
      {/* Toast notifications */}
      {renderNotifications()}

      {/* Main content based on state */}
      {isLoggedIn ? (
        showMainMenu ? renderMainMenu() : renderDashboard()
      ) : (
        activationDone ? (
          renderRegistrationStep()
        ) : (
          renderActivationStep()
        )
      )}
    </div>
  );
}

export default App;
